// TagsIsNil applies the IsNil predicate on the "tags" field.
func TagsIsNil() predicate.PortForward {
	return predicate.PortForward(sql.FieldIsNull(FieldTags))
}

// TagsNotNil applies the NotNil predicate on the "tags" field.
func TagsNotNil() predicate.PortForward {
	return predicate.PortForward(sql.FieldNotNull(FieldTags))
}

// TagsEqualFold applies the EqualFold predicate on the "tags" field.
func TagsEqualFold(v string) predicate.PortForward {
	return predicate.PortForward(sql.FieldEqualFold(FieldTags, v))
}

// TagsContainsFold applies the ContainsFold predicate on the "tags" field.
func TagsContainsFold(v string) predicate.PortForward {
	return predicate.PortForward(sql.FieldContainsFold(FieldTags, v))
}

// HasUser applies the HasEdge predicate on the "user" edge.
func HasUser() predicate.PortForward {
	return predicate.PortForward(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, UserTable, UserColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUserWith applies the HasEdge predicate on the "user" edge with a given conditions (other predicates).
func HasUserWith(preds ...predicate.User) predicate.PortForward {
	return predicate.PortForward(func(s *sql.Selector) {
		step := newUserStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PortForward) predicate.PortForward {
	return predicate.PortForward(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PortForward) predicate.PortForward {
	return predicate.PortForward(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PortForward) predicate.PortForward {
	return predicate.PortForward(sql.NotPredicates(p))
}
